"""Apply ATR-sized triple-barrier labeling to the entries generated by one
baseline strategy (defaults to the best performer from script 03's summary,
or pass a strategy name explicitly).

Usage:
    .venv/bin/python scripts/04_triple_barrier.py data/EURUSD_M15.csv [strategy_name]
"""

import sys
from pathlib import Path

import pandas as pd

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from fxlib import data_loader, labeling, signals  # noqa: E402

DEFAULT_CSV = "data/EURUSD_M15.csv"

BASELINE_PARAMS = {
    "ma_crossover": dict(fast=10, slow=50),
    "rsi_mean_reversion": dict(rsi_window=14, oversold=30, overbought=70, exit_mid=50),
    "atr_breakout": dict(channel_window=20, atr_window=14, atr_mult=0.5),
}

# Barrier sizing: profit-take and stop-loss both at 1x ATR, max hold 16 bars (4h on M15).
PT_MULT = 1.0
SL_MULT = 1.0
MAX_HOLDING_BARS = 16
ATR_WINDOW = 14


def pick_best_strategy() -> str:
    summary_path = Path("results") / "baseline_backtest_summary.csv"
    if not summary_path.exists():
        raise FileNotFoundError(f"{summary_path} not found -- run scripts/03_backtest_baselines.py first")
    summary = pd.read_csv(summary_path)
    best = summary.sort_values("sharpe", ascending=False).iloc[0]
    return best["strategy"]


def main(csv_path: str, strategy_name: str | None):
    df = data_loader.load_mt5_csv(csv_path)
    df = df[~df.index.duplicated(keep="first")]

    if strategy_name is None:
        strategy_name = pick_best_strategy()
    print(f"Using strategy: {strategy_name}")

    signal_fn = signals.BASELINES[strategy_name]
    params = BASELINE_PARAMS[strategy_name]
    signal = signal_fn(df, **params)

    labels = labeling.label_from_signal(
        df, signal, pt_mult=PT_MULT, sl_mult=SL_MULT, max_holding_bars=MAX_HOLDING_BARS, atr_window=ATR_WINDOW
    )

    print(f"\n{len(labels)} labeled trade entries")
    print(f"PT/SL = {PT_MULT}x/{SL_MULT}x ATR({ATR_WINDOW}), max hold = {MAX_HOLDING_BARS} bars")
    print("\nLabel distribution:")
    print(labels["label"].value_counts().sort_index())
    print(f"\nMeta-label positive rate (would-be-profitable trades): {labels['meta_label'].mean():.3f}")
    print("\nBy side:")
    print(labels.groupby("side")["meta_label"].agg(["mean", "count"]))
    print("\nHolding period (bars):")
    print(labels["n_bars_held"].describe())

    out_path = Path("results") / f"triple_barrier_labels_{strategy_name}.csv"
    out_path.parent.mkdir(exist_ok=True)
    labels.to_csv(out_path, index=False)
    print(f"\nSaved labels to {out_path}")


if __name__ == "__main__":
    csv_path = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_CSV
    strategy_name = sys.argv[2] if len(sys.argv) > 2 else None
    main(csv_path, strategy_name)
